timed reactiveclass ActorB {
    knownrebecs {
        ActorA a;
    }
    statevars {
        int internal;
    }

    ActorB() {
        internal = 0;
    }

    msgsrv process(int v) {
        internal = v + 1;
        a.reply(internal) after(1);
    }
}

timed main {
    ActorA a(1);
    ActorB b(a);

    a(b);
